import { useState } from "react";
import { AddressFields } from "./AddressFields";
import { CardPicker } from "./CardPicker";
import { Summary } from "./Summary";
import { messages } from "./messages";

export function CheckoutPage({ invoice, savedCards }: CheckoutProps) {
  const [card, setCard] = useState(savedCards.find((c) => c.isDefault) ?? null);
  const [error, setError] = useState<string | null>(null);
  const [paying, setPaying] = useState(false);

  async function pay() {
    setPaying(true);
    const result = await payInvoice(invoice.id, card);
    setPaying(false);
    if (!result.ok) setError(messages[result.code] ?? messages.unknown);
  }

  return (
    <main className="checkout">
      <h1>Pay invoice {invoice.number}</h1>
      <Summary invoice={invoice} />
      <AddressFields billing={invoice.client.billing} />
      <CardPicker cards={savedCards} selected={card} onSelect={setCard} />
      {error && <p className="error" role="alert">{error}</p>}
      <button onClick={pay} disabled={!card || paying}>
        Pay {formatMoney(invoice.total_cents, invoice.currency)}
      </button>
    </main>
  );
}

